import{_ as e,o as i,c as o,a8 as a}from"./chunks/framework.Dcpyy8JV.js";const m=JSON.parse('{"title":"💡 Progetto Domotico Strategico: Il Sistema Ibrido","description":"","frontmatter":{},"headers":[],"relativePath":"blogs/overview/progetto-domotico.md","filePath":"blogs/overview/progetto-domotico.md"}'),l={name:"blogs/overview/progetto-domotico.md"};function r(n,t,s,d,c,g){return i(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="💡-progetto-domotico-strategico-il-sistema-ibrido" tabindex="-1">💡 Progetto Domotico Strategico: Il Sistema Ibrido <a class="header-anchor" href="#💡-progetto-domotico-strategico-il-sistema-ibrido" aria-label="Permalink to &quot;💡 Progetto Domotico Strategico: Il Sistema Ibrido&quot;">​</a></h1><p>L&#39;obiettivo è costruire un ecosistema <strong>potente, economico e privato</strong>, utilizzando <strong>Home Assistant (HA)</strong> come cuore pulsante. L&#39;approccio ibrido permette di sfruttare il meglio di ogni tecnologia (Zigbee, Thread, Wi-Fi e Cloud) senza restare prigionieri di un singolo marchio.</p><h2 id="🧠-home-assistant-il-cervello-locale-e-aperto" tabindex="-1">🧠 Home Assistant: Il Cervello Locale e Aperto <a class="header-anchor" href="#🧠-home-assistant-il-cervello-locale-e-aperto" aria-label="Permalink to &quot;🧠 Home Assistant: Il Cervello Locale e Aperto&quot;">​</a></h2><p>Home Assistant è il software open-source che funge da <strong>Hub Centrale</strong>. A differenza dei kit commerciali, non dipende dai server di un&#39;azienda specifica.</p><h3 id="perche-scegliere-home-assistant" tabindex="-1">Perché scegliere Home Assistant? <a class="header-anchor" href="#perche-scegliere-home-assistant" aria-label="Permalink to &quot;Perché scegliere Home Assistant?&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Vantaggio Chiave</th><th style="text-align:left;">Descrizione Dettagliata</th><th style="text-align:left;">Impatto nel Sistema</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Privacy &amp; Controllo</strong></td><td style="text-align:left;">I dati restano tra le mura di casa. Nessun abbonamento richiesto.</td><td style="text-align:left;">🔒 Massima Sicurezza</td></tr><tr><td style="text-align:left;"><strong>Multilinguaggio</strong></td><td style="text-align:left;">Parla simultaneamente Wi-Fi, Zigbee, Z-Wave, Bluetooth e Matter.</td><td style="text-align:left;">🌐 Interoperabilità</td></tr><tr><td style="text-align:left;"><strong>Automazioni Evolute</strong></td><td style="text-align:left;">Logiche &quot;Se... Allora...&quot; granulari tra marche diverse (es. Sensore Aqara ➔ Luce Philips).</td><td style="text-align:left;">⚡ Potenza Illimitata</td></tr><tr><td style="text-align:left;"><strong>Hardware Flessibile</strong></td><td style="text-align:left;">Gira su Raspberry Pi, Mini PC ricondizionati o NAS.</td><td style="text-align:left;">💰 Costo Iniziale Contenuto</td></tr><tr><td style="text-align:left;"><strong>Dashboard Custom</strong></td><td style="text-align:left;">Interfacce personalizzate per tablet, smartphone e PC.</td><td style="text-align:left;">📱 Esperienza Utente</td></tr></tbody></table><h2 id="🛠️-l-architettura-del-sistema-ibrido" tabindex="-1">🛠️ L&#39;Architettura del Sistema Ibrido <a class="header-anchor" href="#🛠️-l-architettura-del-sistema-ibrido" aria-label="Permalink to &quot;🛠️ L&#39;Architettura del Sistema Ibrido&quot;">​</a></h2><p>Un sistema &quot;Ibrido&quot; combina diversi protocolli radio e livelli di connessione per massimizzare l&#39;efficienza.</p><h3 id="_1-livello-radio-locale-puro-📡" tabindex="-1">1. Livello Radio (Locale Puro) 📡 <a class="header-anchor" href="#_1-livello-radio-locale-puro-📡" aria-label="Permalink to &quot;1. Livello Radio (Locale Puro) 📡&quot;">​</a></h3><ul><li><strong>Zigbee / Thread (Spina Dorsale):</strong> Utilizzato per la maggior parte dei sensori. Collegato direttamente a HA tramite un <strong>Dongle USB</strong> (es. SkyConnect o Sonoff ZBDongle-E). <ul><li><em>Vantaggio:</em> I sensori non passano dal cloud e non intasano il Wi-Fi.</li></ul></li><li><strong>Z-Wave (Opzionale):</strong> Riservato a dispositivi critici (valvole idriche, serrature) per la sua banda dedicata a 868 MHz che evita ogni interferenza.</li></ul><h3 id="_2-livello-wi-fi-lan-control-🔌" tabindex="-1">2. Livello Wi-Fi (LAN Control) 🔌 <a class="header-anchor" href="#_2-livello-wi-fi-lan-control-🔌" aria-label="Permalink to &quot;2. Livello Wi-Fi (LAN Control) 🔌&quot;">​</a></h3><ul><li><strong>Dispositivi Shelly / ESPHome / Tasmota:</strong> Prodotti che nascono per il Wi-Fi ma che HA può controllare direttamente tramite la rete locale (<strong>API Locali</strong>), bypassando i server del produttore (es. integrazione Tuya Local, Shelly, o dispositivi flashati con ESPHome). <ul><li><em>Vantaggio:</em> Reattività immediata e funzionamento garantito anche se internet si interrompe.</li></ul></li></ul><h3 id="_3-livello-cloud-ibridazione-funzionale-☁️" tabindex="-1">3. Livello Cloud (Ibridazione Funzionale) ☁️ <a class="header-anchor" href="#_3-livello-cloud-ibridazione-funzionale-☁️" aria-label="Permalink to &quot;3. Livello Cloud (Ibridazione Funzionale) ☁️&quot;">​</a></h3><p>Non tutto il cloud è &quot;cattivo&quot;. In un sistema ibrido, usiamo il cloud solo dove aggiunge valore reale:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Funzionalità Cloud</th><th style="text-align:left;">Esempio Pratico</th><th style="text-align:left;">Ruolo nel Sistema</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Mappe Avanzate</strong></td><td style="text-align:left;">Robot Aspirapolvere (Roborock, Dreame).</td><td style="text-align:left;">HA avvia la pulizia, l&#39;App Cloud gestisce la mappa 3D.</td></tr><tr><td style="text-align:left;"><strong>Scene Dinamiche</strong></td><td style="text-align:left;">Effetti &quot;Party&quot; o &quot;Aurora&quot; di Philips Hue o Nanoleaf.</td><td style="text-align:left;">HA attiva la scena, il Cloud gestisce le sfumature complesse.</td></tr><tr><td style="text-align:left;"><strong>Assistenti Vocali</strong></td><td style="text-align:left;">Integrazione con Alexa o Google Home.</td><td style="text-align:left;">HA espone i dispositivi, il Cloud gestisce il riconoscimento vocale.</td></tr><tr><td style="text-align:left;"><strong>Notifiche Remote</strong></td><td style="text-align:left;">Notifiche push su smartphone fuori casa.</td><td style="text-align:left;">HA invia l&#39;alert tramite il servizio cloud di Nabu Casa.</td></tr></tbody></table><h2 id="📋-raccomandazione-tecnica-per-il-2026" tabindex="-1">📋 Raccomandazione Tecnica per il 2026 <a class="header-anchor" href="#📋-raccomandazione-tecnica-per-il-2026" aria-label="Permalink to &quot;📋 Raccomandazione Tecnica per il 2026&quot;">​</a></h2><p>Per chi inizia oggi, ecco la configurazione &quot;Best Buy&quot; consigliata:</p><h3 id="⚙️-hardware-centrale" tabindex="-1">⚙️ Hardware Centrale <a class="header-anchor" href="#⚙️-hardware-centrale" aria-label="Permalink to &quot;⚙️ Hardware Centrale&quot;">​</a></h3><ul><li><strong>Server:</strong> Mini PC (Intel N100) o Raspberry Pi 5.</li><li><strong>Radio:</strong> Dongle USB &quot;Universal&quot; (supporto combinato Zigbee + Thread/Matter).</li></ul><h3 id="🛒-scelta-dei-dispositivi" tabindex="-1">🛒 Scelta dei Dispositivi <a class="header-anchor" href="#🛒-scelta-dei-dispositivi" aria-label="Permalink to &quot;🛒 Scelta dei Dispositivi&quot;">​</a></h3><ol><li><strong>Sensori (Zigbee):</strong> Aqara (clima, movimento, porte) o IKEA Vallhorn.</li><li><strong>Illuminazione:</strong> Philips Hue (per la qualità) o IKEA Tradfri (per il risparmio).</li><li><strong>Attuatori di Potenza (Wi-Fi LAN):</strong> Shelly Plus 1PM o Shelly 2PM per tapparelle e carichi pesanti.</li><li><strong>Clima:</strong> Valvole termostatiche Zigbee o integrazioni locali per condizionatori (es. Sensibo o Broadlink).</li></ol><h3 id="🚀-metodo-di-integrazione" tabindex="-1">🚀 Metodo di Integrazione <a class="header-anchor" href="#🚀-metodo-di-integrazione" aria-label="Permalink to &quot;🚀 Metodo di Integrazione&quot;">​</a></h3><ul><li><strong>Preferisci sempre il controllo LOCALE</strong> (Zigbee o Wi-Fi con API locali).</li><li><strong>Usa il CLOUD come accessorio</strong> (solo per voce, mappe e accesso remoto sicuro via Nabu Casa).</li></ul>',23)])])}const h=e(l,[["render",r]]);export{m as __pageData,h as default};
